def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = (bins >= item) & (bins > 0)
    utilization = 1.0 - (remaining / (bins + 1e-8))
    score = -np.log(remaining + 1e-5) * (np.sin(np.pi * utilization) + 1.05)
    return np.where(valid, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_buffer = 0.05 * bins
    score = -np.exp(np.abs(remaining - target_buffer))
    return np.where((bins < item) | (bins <= 0), -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = (bins >= item) & (bins > 0)
    utilization = 1.0 - (remaining / (bins + 1e-8))
    score = np.exp(-remaining) / (np.square(utilization - 0.7) + 1e-5)
    return np.where(valid, score, -np.inf)
